INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_hyperscaler', 'hyperscaler', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_hyperscaler_0', 'e_hyperscaler', 0, 'hyperscaler', '[]', 'One of the few cloud providers running compute and storage at a scale you cannot exhaust.', 'It is a category, not a compliment. Applied to your own platform or to a fast-growing vendor it will get you corrected by anyone who knows the term, and in a room that does not know it, it reads as jargon for big cloud. The useful move is to say what follows from the category: pricing power, data residency, or the fact that you will never out-spend them.', 'We are not going to beat a hyperscaler on inference cost, so the case has to rest on the data staying ours.', '[{"text":"A steering committee asks why the firm cannot simply build the same capacity in-house, and you need the collective noun for the three vendors that already have it.","setting":"work"},{"text":"An MD wants to know why frontier model training happens at only a few companies in the world, and the answer is who owns the hardware.","setting":"work"},{"text":"Procurement asks which suppliers count as strategic infrastructure rather than ordinary software vendors, and you want the term for that tier.","setting":"work"},{"text":"Writing an architecture note, you need one word for AWS, Azure and Google Cloud as a class so you stop listing all three every time.","setting":"work"}]', '["A data centre a company builds and runs purely for its own internal systems.","A vendor that resells another company''s cloud capacity under its own brand.","The unit of computing you rent by the hour and give back when the job is finished.","A pricing model where you pay only for the computing you actually consume, billed by the second.","A company that keeps its servers in its own building rather than renting them from anyone."]', '["verbose","persist","bolster","despondent","enmeshed"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
