INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_gravitas', 'gravitas', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_gravitas_0', 'e_gravitas', 0, 'gravitas', '[]', 'A weight and seriousness in how someone carries themselves that makes a room listen.', 'Never said about yourself, and rarely to someone''s face. As feedback it is close to unfalsifiable and often a proxy for resembling the people already in the senior seats, so if you use it in a development conversation you owe the person a concrete behaviour to work on. Said of a peer in a standup it sounds arch; keep it for rooms where the stakes are real.', 'He took the audit question with real gravitas, which is why the board stopped pushing on it.', '[{"text":"A new director takes a hostile question from the board without flinching, and you want the word for what made the room settle.","setting":"work"},{"text":"You are telling a colleague why a senior audience did not take her recommendation seriously, and it was not the content.","setting":"work"},{"text":"A sponsor asks what is missing from the candidate who is technically the strongest on the shortlist.","setting":"work"},{"text":"A friend describes a wedding speech given by someone whose bearing made the whole room go quiet.","setting":"life"},{"text":"Watching an actor play a judge, you want the word for the weight he carries that the younger cast do not.","setting":"life"}]', '["The habit of speaking far longer than the point needs.","The nerves that show when someone is asked a question they were not expecting.","A reputation for being right, built up over years of small correct calls.","The formal authority a role carries, written down in a job description and an org chart.","A speaking style that fills a room with energy and gets people excited about a plan."]', '["primitive","by and large","lean on","dogfooding","squarely"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
