INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_executive_presence_finesse', 'executive presence/finesse', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_executive_presence_finesse_0', 'e_executive_presence_finesse', 0, 'executive presence', '[]', 'Coming across as calm, clear and senior enough to be handed a decision.', 'One of the few phrases you can only ever say about someone else. As feedback it is notoriously vague and is often heard as be more like us, so it lands as a coded judgement unless you attach a concrete behaviour to it: cut the preamble, lead with the recommendation, stop narrating your working. Do not use it as a polite cover for a decision you have already made about someone.', 'Her content is watertight; what we are coaching is executive presence, starting with not burying the ask on slide nine.', '[{"text":"A brilliant engineer keeps losing the room in front of the investment committee, and you need the name for the thing he is missing.","setting":"work"},{"text":"Your manager asks what separates two candidates for a director role whose track records are identical.","setting":"work"},{"text":"You are designing a coaching plan for someone who knows more than anyone in the room but is never the one the MD turns to.","setting":"work"},{"text":"A friend preparing for a panel interview asks what the panel is really judging in the first two minutes.","setting":"life"}]', '["A record of delivering what you promised, quarter after quarter.","The number of people who report to you, directly and indirectly.","The ability to speak a second language well enough to negotiate in it.","The set of decisions a leader is formally allowed to make without asking.","The rank a job sits at in a company''s grading system, published for everyone to see."]', '["persist","broad","fan-out","daily driver","wordsmith"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
