INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_top_brass', 'top brass', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_top_brass_0', 'e_top_brass', 0, 'top brass', '["the brass"]', 'The most senior people in an organisation, talked about as one group from below.', 'It always marks you as outside the group, which is the charm of it in a corridor or a team channel and the problem with it anywhere formal. In a paper write the executive committee; said to one of them directly it is either flippant or faintly insubordinate, and said with a sigh it tells everyone how you feel about a decision you are supposed to be carrying. Borrowed from the military, and informal to the point of being wry.', 'The brass are in the building on Thursday, so keep the demo to ten minutes and skip the architecture slide.', '[{"text":"You are warning your team in a channel that the most senior leaders in the firm will be sitting in on Thursday''s review, and you want the informal collective for them.","setting":"work"},{"text":"Over coffee a peer asks who actually killed the project, and the answer is people neither of you has ever met.","setting":"work"},{"text":"A friend complains that the decision to close her branch came from people at head office who have never once visited it.","setting":"life"},{"text":"Your uncle is telling army stories about the officers who came round for inspection, and you want the wry phrase for them.","setting":"life"}]', '["A committee formed to review one decision and then dissolved.","The people who actually do the work, as distinct from those who plan it.","The founders of a company, whether or not they still hold a formal role in it.","The layer of managers sitting between the front line and the people who set strategy.","Everyone in a company who is not part of the leadership team, spoken of as one body."]', '["failure mode","sandbox","substantial","verifiable rewards","tectonic shift"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_top_brass_0_recognition', 's_top_brass_0', 'recognition', NULL, NULL, 16, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_top_brass_0_identify', 's_top_brass_0', 'identify', NULL, NULL, 17, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
