INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_buy_in', 'buy-in', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_buy_in_0', 'e_buy_in', 0, 'buy-in', '["buy in"]', 'Genuine agreement from the people whose help you need, not just their signature.', 'Not a synonym for sign-off. Claiming you have it when what you actually have is a signature is the kind of statement that collapses at the first delivery slip, and the collapse is public. Said downward it can also sound like you plan to manage people into agreeing rather than ask them, so be careful announcing that you need to get it from your own team.', 'We have the funding, what we do not have is buy-in from the two teams who would have to change how they release.', '[{"text":"The steering committee has approved your programme, but the two delivery leads whose work it changes still think it is a mistake.","setting":"work"},{"text":"You are explaining to a sponsor why a technically finished rollout has stalled: the people whose process it changes were never really with you.","setting":"work"},{"text":"Writing a plan, you need a word for the thing a signature on its own does not give you.","setting":"work"},{"text":"Your family agrees in principle to the mountain holiday, but half of them are plainly humouring you.","setting":"life"},{"text":"A neighbour wants the shared driveway resurfaced and asks what she needs from the other households before anyone spends a penny.","setting":"life"}]', '["A formal signature recorded so that a project may begin.","The money a partner puts in to take a share of a business.","The share of a market a product has taken from its competitors.","Written permission from a committee that has reviewed both the risks and the cost.","The quiet compliance of a team that has stopped arguing but has not changed its mind."]', '["serialize","eschew","long-horizon","esoteric","semantic layer"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
