INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_obscure', 'obscure', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_obscure_0', 'e_obscure', 0, 'obscure', '["obscures","obscured"]', 'Little known or hard to make out, or to keep something from being seen or understood.', 'The verb accuses nobody, which is the whole reason to reach for it. Saying the dashboard obscures the failure rate names a design problem; saying it obfuscates the failure rate says someone meant to mislead. Keep it pointed at the artefact rather than the person, because aimed at a colleague''s explanation it is still a criticism, just a quieter one.', 'The monthly average obscures the two days when latency tripled, so let us show the daily line instead.', '[{"text":"A monthly rollup is hiding the two bad days inside it, and you want a neutral verb for what the rollup is doing.","setting":"work"},{"text":"You are pushing back on a reference to a library that almost nobody in the room will have heard of.","setting":"work"},{"text":"A summary metric is correct but stops people seeing the variance underneath, and you want to say so without implying anyone did it on purpose.","setting":"work"},{"text":"A friend recommends a film that almost nobody has seen, and you want the word for how far off the beaten track it is.","setting":"life"},{"text":"Fog has taken the mountains at the end of the valley out of view, and you want a slightly formal word for what it is doing.","setting":"life"}]', '["Recognised instantly by almost everyone who sees it.","Repeated so often that it has lost whatever meaning it started with.","So familiar that people stop noticing it is there at all.","A claim that is easy to state and impossible for anyone outside the company to check.","A system that is still running long after the team that built it moved on to other work."]', '["superset","advocate","unequivocal","lean on","verbose"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
