INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_trivial_nontrivial', 'trivial/nontrivial', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_trivial_nontrivial_0', 'e_trivial_nontrivial', 0, 'trivial', '[]', 'So small or easy that it is not worth spending time on.', 'Said about someone else''s work it is dismissive whatever you intended, because it tells them their week was not worth much. It is safest about your own work, and it is a hostage to fortune even there: the trivial change that took production down is the one everybody remembers you calling trivial.', 'The schema change is trivial; the migration for the three teams downstream is not.', '[{"text":"Your tech lead asks how big the config change is, and the honest answer is that reviewing it will take longer than making it.","setting":"work"},{"text":"You are separating the half of the migration that takes an afternoon from the half that takes a month, and you need the dismissive adjective for the easy half.","setting":"work"},{"text":"A friend is agonising over two phone plans that differ by a pound a month, and you want a word for the size of that difference.","setting":"life"},{"text":"Someone apologises at length for a favour that cost you nothing, and you want one adjective to wave it away.","setting":"life"}]', '["Deferred to a later release on purpose.","Cheap to build and expensive to run.","Left undone because nobody ever owned it.","Small in size but serious in what it sets off downstream.","Difficult to explain but easy to do once you have seen it."]', '["sponsorship","finesse","substantial","buy-in","north star"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_trivial_nontrivial_0_recognition', 's_trivial_nontrivial_0', 'recognition', NULL, NULL, 40, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_trivial_nontrivial_0_identify', 's_trivial_nontrivial_0', 'identify', NULL, NULL, 41, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_trivial_nontrivial_0_reverse', 's_trivial_nontrivial_0', 'reverse', NULL, NULL, 42, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_trivial_nontrivial_0_production', 's_trivial_nontrivial_0', 'production', NULL, NULL, 43, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_trivial_nontrivial_1', 'e_trivial_nontrivial', 1, 'nontrivial', '["non-trivial"]', 'Not simple, and harder or larger than the person asking has assumed.', 'A technical audience''s word, and it works because it is dry. In front of a board it can read as evasive, because they hear hard and immediately want a number, so put one straight after it. It also implies you have already looked, so it is a poor place to hide an estimate you have not actually made.', 'Rewiring auth for the new tenant model is nontrivial, so call it three sprints rather than a fortnight.', '[{"text":"An MD asks whether adding a second language to the assistant is just a config change, and it is a month of work.","setting":"work"},{"text":"You want to warn a project manager that a change she assumes is small reaches into three services, using understatement rather than alarm.","setting":"work"},{"text":"A friend asks whether getting the sofa up two flights of stairs is a job for two people, and it is a great deal more work than she thinks.","setting":"life"},{"text":"You are telling someone that learning to drive a manual car is harder than they are assuming, without putting them off it.","setting":"life"}]', '["Simple to describe and simple to build.","Impossible with the tools currently available at any price.","Expensive in money but cheap in the time it takes to finish.","Well understood by the team that owns it and by nobody else in the building.","Held up by a dependency on another team rather than by the work itself."]', '["second order effects","by and large","verbose","tacit knowledge","build that muscle"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_trivial_nontrivial_1_recognition', 's_trivial_nontrivial_1', 'recognition', NULL, NULL, 44, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
