INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_trivial_nontrivial_1_production', 's_trivial_nontrivial_1', 'production', NULL, NULL, 47, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_substantiate_substantial', 'substantiate/substantial', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_substantiate_substantial_0', 'e_substantiate_substantial', 0, 'substantiate', '["substantiated"]', 'To back a claim with evidence that someone else can check.', 'Asking someone to substantiate something is a challenge however gently you say it, and everyone in the room hears the doubt. Used about your own claims it reads as rigour; used about a colleague''s in front of their boss it reads as an ambush, so if you must, ask for the source rather than for substantiation.', 'I can substantiate the thirty per cent figure from two quarters of tickets, it is not a vendor number.', '[{"text":"A director accepts your recommendation and then asks where the number came from, and you want the verb for supplying that.","setting":"work"},{"text":"You are reviewing a paper whose central claim rests on one unsourced statistic, and you want to name politely what it is missing.","setting":"work"},{"text":"A friend repeats a health claim they read online, and you want the word for what you would want before believing it.","setting":"life"},{"text":"An insurer asks you to back the value of a lost item with something more than your word for it.","setting":"life"}]', '["To repeat a claim until people accept it.","To state something plainly and without hedging.","To write down what was decided so it can be found later.","To argue a case on behalf of somebody who is not in the room.","To take an existing figure and adjust it for inflation over time."]', '["panopticon","play it by ear","tectonic shift","disambiguate","harness"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substantiate_substantial_0_recognition', 's_substantiate_substantial_0', 'recognition', NULL, NULL, 48, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substantiate_substantial_0_identify', 's_substantiate_substantial_0', 'identify', NULL, NULL, 49, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substantiate_substantial_0_reverse', 's_substantiate_substantial_0', 'reverse', NULL, NULL, 50, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substantiate_substantial_0_production', 's_substantiate_substantial_0', 'production', NULL, NULL, 51, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_substantiate_substantial_1', 'e_substantiate_substantial', 1, 'substantial', '[]', 'Large enough to matter, said of an amount or a change without giving a number.', 'A hedge that sounds like a fact. In front of anyone numerate, substantial savings invites the immediate question of how much, and if you cannot answer you have lost more ground than the vague word ever bought you. Keep it for cases where the figure is genuinely not yours to give, and give the figure everywhere else.', 'There is a substantial gap between what the pilot proved and what the rollout is assuming.', '[{"text":"You want to call the cost reduction meaningful in a paper where you are not allowed to publish the exact figure.","setting":"work"},{"text":"A colleague''s contribution to the project went far beyond a review, and you want to credit it in writing.","setting":"work"},{"text":"Describing a restaurant to a friend, you want a word for portions that genuinely fill you rather than decorate the plate.","setting":"life"},{"text":"A neighbour asks what the roof repair cost, and you want to convey that it was a lot without naming the figure.","setting":"life"}]', '["Small enough to ignore for now.","Measured precisely and reported to two decimal places.","Growing steadily but from a very small starting point.","Set aside in a budget for costs that have not yet been identified in any detail.","Counted twice by mistake because two systems both reported the same transaction."]', '["bolster","long-horizon","finesse","north star","hyperscaler"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substantiate_substantial_1_recognition', 's_substantiate_substantial_1', 'recognition', NULL, NULL, 52, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substantiate_substantial_1_identify', 's_substantiate_substantial_1', 'identify', NULL, NULL, 53, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substantiate_substantial_1_reverse', 's_substantiate_substantial_1', 'reverse', NULL, NULL, 54, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_substantiate_substantial_1_production', 's_substantiate_substantial_1', 'production', NULL, NULL, 55, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_delibrate_intentional', 'delibrate/intentional', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_delibrate_intentional_0', 'e_delibrate_intentional', 0, 'deliberate', '["intentional","deliberately","intentionally"]', 'Done on purpose and with thought, rather than by accident or drift.', 'About someone else''s action it converts a mistake into a choice, which is why it turns up in incident reviews, complaints and disciplinary letters. About your own plan it has become management shorthand for going slowly, so a sponsor who is already impatient hears we are being deliberate as a delay dressed up as a virtue. If all you mean is that the outcome was not an accident, on purpose is the plainer and safer phrase.', 'The gap in the rollout schedule is deliberate, we want a full month of production data before the next region goes live.', '[{"text":"A sponsor reads the gap in your roadmap as a slip, and you need to say the pause was chosen rather than accidental.","setting":"work"},{"text":"In an incident review you have to state whether the configuration change was made knowingly, and it was.","setting":"work"},{"text":"You are describing a hiring approach that moves slowly by design, because each early hire shapes the team.","setting":"work"},{"text":"A friend asks whether you left a name off the invitation by mistake, and you did not.","setting":"life"},{"text":"Someone speaks in an unhurried way with every word chosen, and you want the adjective for that manner.","setting":"life"}]', '["Done quickly, before anyone has time to object.","Agreed by everyone in the room without a vote.","Left to whoever picks it up first, with no owner named anywhere.","Repeated so often that it has become a habit nobody questions any more.","Chosen because it was the only option anybody could think of at the time."]', '["bespoke","center of excellence","panopticon","idempotent","unequivocal"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
