INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_daily_driver', 'daily driver', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_daily_driver_0', 'e_daily_driver', 0, 'daily driver', '[]', 'The tool you actually use every day, rather than a backup or one you are still testing.', 'It is a claim of real use, and that is the whole value of it: calling a tool your daily driver says you have hit its rough edges, so expect the follow-up question about what they are. Said of something you have opened twice it is exactly the kind of overclaim a sceptical engineer will test. It is also casual, so in a written recommendation or a vendor evaluation it reads as breezy where you wanted evidence. Borrowed from cars and now said of a laptop, an editor, a model.', 'Claude is my daily driver, I keep the others around for the one or two jobs they are better at.', '[{"text":"A colleague asks which of the three coding assistants you actually reach for, not which ones you have tried.","setting":"work"},{"text":"In a tooling review you want to separate the editor most engineers live in from the ones installed once and forgotten.","setting":"work"},{"text":"A friend with three bicycles is asked which one he rides to work and which he keeps for weekends.","setting":"life"},{"text":"You keep a good camera for holidays and photograph everything else on your phone, and you want the term for the phone.","setting":"life"}]', '["A tool bought and never installed.","A spare kept in a drawer in case the main one fails.","The version of a product given to reviewers before release.","The tool a company has standardised on and pays for, whether or not anyone enjoys using it.","A product used only for demonstrations, set up carefully so nothing goes wrong on stage."]', '["tectonic shift","inroads","hot-swap","asymmetric","elucidate"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
