INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_incremental', 'incremental', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_incremental_0', 'e_incremental', 0, 'incremental', '["incrementally"]', 'Proceeding by small additions, each one adding a little to what is already there.', 'The word has two temperatures and the room picks which one. About delivery it is a virtue; about results it is faint praise, and applied to a benefits case it is how a committee says not worth the money without having to argue. Decide which one your audience will hear before you use it about your own work. In a finance conversation it means something different again, the extra amount on top of the baseline rather than a small one.', 'The gains are incremental per release, and it is the compounding across two quarters that the case actually rests on.', '[{"text":"A committee asks how you will de-risk an eighteen-month programme, and your answer is small releases that each stand on their own.","setting":"work"},{"text":"You are describing model improvements that are real but modest, and you want the honest word for them before somebody else uses it against you.","setting":"work"},{"text":"You are explaining how you are learning a language: twenty minutes a night, nothing dramatic.","setting":"life"},{"text":"A friend asks whether the new phone is worth the upgrade, and every improvement in it is a small one.","setting":"life"}]', '["Done all at once, with no way back.","Replaced entirely rather than repaired.","Growing by a fixed percentage each period rather than a fixed amount.","A change that removes a feature instead of adding one, to keep the product simple.","Work that cannot be split up, because none of it is any use until all of it is done."]', '["continuum","squarely","tectonic shift","serialize","build that muscle"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
