INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_progressive', 'progressive', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_progressive_0', 'e_progressive', 0, 'progressive', '["progressively"]', 'Advancing in stages, each stage going further than the last.', 'The word has a political life, so about people, policy or an organisation''s values it will be read that way whatever you meant, and in that reading it is a label rather than a description. Say phased or staged there. In a pricing or tax conversation it means something different again, rates that rise with the amount. Keep it for delivery and design, where the technical reading is the only one available.', 'We will do a progressive rollout, one desk this week, the floor next week, and the region only after two clean weeks.', '[{"text":"You are proposing to widen a release from one desk to a floor to the whole region, one step at a time, and want the adjective for that shape of rollout.","setting":"work"},{"text":"A designer asks what to call an interface that shows the simple case first and reveals the advanced controls only when they are asked for.","setting":"work"},{"text":"In a risk paper you need a word for exposure that grows in planned stages rather than arriving all at once.","setting":"work"},{"text":"Your optician is describing lenses whose strength changes gradually from the top of the lens to the bottom.","setting":"life"},{"text":"A friend''s training plan adds a little more distance every week, and you want the adjective for that kind of build-up.","setting":"life"}]', '["Released to everyone at the same moment.","Repeated identically each time it runs.","Held back until every part of it is finished and signed off.","Rolled back to the previous version the moment anything looks wrong.","Reversed one step at a time until the system is back where it started."]', '["second order effects","unequivocal","tacit knowledge","frontier","vertical"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
