INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_ducks_in_a_row', 'ducks in a row', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_ducks_in_a_row_0', 'e_ducks_in_a_row', 0, 'ducks in a row', '["get your ducks in a row","ducks lined up"]', 'All the preparation done in advance, so nothing is missing when the moment comes.', 'It is homely and slightly folksy, which makes it warm between peers and patronising downward, and telling a senior stakeholder to get their ducks in a row implies they are disorganised. It belongs to speech: in a written paper it reads as though you could not be bothered to name which preparation you actually meant.', 'Before this goes to the committee let us get our ducks in a row on the cost model and the security sign-off.', '[{"text":"Two weeks before a board paper you want to tell your team informally that every approval, number and sign-off has to be settled first.","setting":"work"},{"text":"A peer is about to ask for headcount with no business case and no hiring plan ready behind it.","setting":"work"},{"text":"A friend is buying a flat and has not yet sorted the mortgage, the survey or the solicitor.","setting":"life"},{"text":"Before a family trip abroad you want a phrase for getting the passports, the insurance and the bookings all settled in advance.","setting":"life"}]', '["A list of everything that could go wrong, each with an owner.","Deciding as you go, taking your lead from how things actually develop.","The order in which tasks must run, drawn as a chain of dependencies.","A meeting held after the event to work out what went wrong and who should fix it.","The single person whose approval is needed before anything else is allowed to move."]', '["disambiguate","trivial","ephemeral","wordsmith","semantic layer"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
