INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_watch_outs', 'watch outs', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_watch_outs_0', 'e_watch_outs', 0, 'watch outs', '["watch-outs","watchouts","watch out"]', 'A short list of things likely to go wrong, given in advance so nobody is surprised.', 'This is consultant and steering-committee register, natural on a slide and slightly odd said aloud anywhere else. The real trap is using it as a softer label for something that is actually a risk: relabelling it removes the owner and the mitigation, and a watch out is what an unmanaged problem is called right up until it fires. Flag it this way only when attention genuinely is the whole response.', 'Two watch outs before we start: the data refresh lands mid-demo, and Legal has not seen the retention wording yet.', '[{"text":"You are opening a steering committee update and want to flag two things likely to trip the group up, short of raising them as formal risks.","setting":"work"},{"text":"A colleague is taking over your demo next week and needs to know the two places it usually goes wrong.","setting":"work"},{"text":"Writing a one-page handover, you need a heading for the short list of things that catch people by surprise.","setting":"work"},{"text":"A friend is renting a flat in a neighbourhood you know well, and you want to name two things she should keep an eye on before she signs.","setting":"life"}]', '["The one thing that must go right for the plan to work at all.","A list of everything already agreed, kept so that nobody reopens it.","Problems discovered only after a release has gone out to customers.","A written summary of what a meeting decided, circulated afterwards to everyone who missed it.","The set of conditions that must hold true for an estimate to be worth anything at all."]', '["contrived","serialize","disambiguate","primitive","persistence"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_watch_outs_0_recognition', 's_watch_outs_0', 'recognition', NULL, NULL, 76, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
