INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_blanket_approval_carte_blanche', 'blanket approval/carte blanche', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_blanket_approval_carte_blanche_0', 'e_blanket_approval_carte_blanche', 0, 'blanket approval', '["carte blanche"]', 'Permission given once in advance to cover a whole class of decisions.', 'Claiming it is far riskier than having it. Tell a committee you have blanket approval and you have invited someone to go and check, and permissions of this shape almost always turn out to have had conditions attached that nobody wrote down. Carte blanche carries a whiff of indulgence on top: about someone else it implies they are unsupervised, about yourself it sounds like a boast.', 'We do not have blanket approval for production data, it is per use case, and the last one took three weeks.', '[{"text":"A team believes one sign-off last quarter covers every future use of customer data, and you need the phrase for what they think they have.","setting":"work"},{"text":"A sponsor offers to let you make all the tooling decisions for the year without coming back to him each time.","setting":"work"},{"text":"You are drafting a governance note about which decisions need a case-by-case review and which do not.","setting":"work"},{"text":"A friend''s parents have told her to plan the anniversary party however she likes, with no limit on the budget.","setting":"life"},{"text":"A neighbour is letting the builder choose every fitting in the new kitchen, with no say in it at all.","setting":"life"}]', '["Approval that expires if it is not used within a set period.","A decision taken by one person and announced without discussion.","A rule that applies to everyone except those who ask to be excused.","A requirement that every single case be reviewed on its own before it can proceed.","A standing instruction to stop work the moment a particular threshold is crossed."]', '["obscure","fearless forecast","failure mode","tacit knowledge","heuristic"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
