INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_rectify', 'rectify', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_rectify_0', 'e_rectify', 0, 'rectify', '["rectified"]', 'To put right something that went wrong, such as an error or an unmet obligation.', 'It concedes fault, which is precisely why it belongs in audit responses, complaints and regulatory letters and precisely why it is the wrong word for routine work. Telling an auditor you will rectify the pipeline says there was a defect; saying you will update it says nothing of the kind. Use it when the admission is the point, and never as a decorative synonym for change.', 'The retention setting was wrong on two buckets, we rectified it on Tuesday and the evidence is on the ticket.', '[{"text":"An audit finds a control was misconfigured for three months, and your written reply has to promise to put it right.","setting":"work"},{"text":"A customer was invoiced twice and you are writing the apology and the remedy in a single sentence.","setting":"work"},{"text":"In a post-incident note you want a formal verb for undoing the damage the bad deploy caused.","setting":"work"},{"text":"A council tax bill has you in the wrong band and you want a formal verb for what you are asking them to do.","setting":"life"},{"text":"You gave a friend advice resting on an assumption that turned out to be wrong, and you want to set it straight properly.","setting":"life"}]', '["To make a bad situation worse.","To work around a fault instead of removing it.","To agree that something is wrong and leave it as it is.","To record a fault in a register so that somebody else can decide what to do about it.","To change something that was already working, in the hope of making it a little better."]', '["community of practice","failure mode","first principles","cognizant","second order effects"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
