INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_elucidate', 'elucidate', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_elucidate_0', 'e_elucidate', 0, 'elucidate', '[]', 'To explain something already said or written by laying out the reasoning behind it.', 'It is a formal word, and spoken it can sound like you are performing. Asking a person to elucidate is a half-step colder than asking them to explain, because it says they were not clear; it lands better in writing, and better aimed at a document than at the author. It also promises the thing gets clearer, not longer. More words that still do not land is the opposite move, and someone will say so.', 'The deck lands the recommendation but never elucidates how we got to that number, and that is the part the committee will push on.', '[{"text":"A steering committee accepts your recommendation but says the reasoning behind one number is a black box. You are writing back to promise the appendix will open it up.","setting":"work"},{"text":"A colleague''s design doc states a decision without showing the trade-off behind it, and in review you want to ask them to bring that reasoning into the open.","setting":"work"},{"text":"Your father repeats the conclusion of a health article without any of what it argued, and you want him to take you through the actual case it made.","setting":"life"},{"text":"A book group is stuck on a chapter that one member plainly understood, and you want to invite them to open it up for everyone.","setting":"life"}]', '["To make something deliberately hard to follow so the plain version stays out of reach.","To go back over a draft and tighten the phrasing without changing what it says.","To back a claim with evidence that someone else can go and check for themselves.","To put right something that was wrong, such as an error, an imbalance, or a missed duty.","To ask someone to talk through what they have learned, informally and without an agenda."]', '["flywheel effect","despondent","progressive","ephemeral","surreptitiously"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
