INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_despondent', 'despondent', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_despondent_0', 'e_despondent', 0, 'despondent', '["despondency"]', 'So low that you have given up expecting things to get better.', 'It is a heavy word about someone''s inner state, close to a diagnosis, and it travels: said about a named colleague it will be repeated back to them. It is also about hopelessness, not disappointment, so after one bad quarter people are deflated, not despondent, and the stronger word makes a room stop and ask whether you are all right. About yourself in a professional setting it overshares.', 'I would not say the team is despondent, but a third slipped date has taken something out of them.', '[{"text":"A friend has failed the same exam twice and has stopped talking about a third attempt. Someone asks how they are doing.","setting":"life"},{"text":"Your sister''s dog died a fortnight ago and she has not been out of the house since. A neighbour asks after her and sad is too small a word.","setting":"life"},{"text":"You are describing the week after a rejection, when nothing seemed worth beginning.","setting":"life"},{"text":"In a private one-to-one you need to tell your manager what a year of cancelled projects has done to one person''s outlook.","setting":"work"},{"text":"A character in the novel you are reading has stopped expecting anything to change, and you are explaining the book to someone.","setting":"life"}]', '["Aware of something and visibly taking it into account.","Weight and seriousness in how a person carries themselves.","Tangled into something so completely that you can no longer act on your own.","Alert to something and picking up its signals early enough to adjust.","Done on purpose and after thought, rather than by accident or by drift."]', '["obfuscate","enmeshed","verifiability","frontrunner","esoteric"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_despondent_0_recognition', 's_despondent_0', 'recognition', NULL, NULL, 100, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
