INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_amenable', 'amenable', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_amenable_0', 'e_amenable', 0, 'amenable', '[]', 'Open to something without having agreed to it, or well suited to a particular treatment.', 'Its softness is the whole point and it evaporates in the retelling. Tell a room the CFO was amenable and half of them will hear that he agreed, and when he objects three weeks later that gap is yours to explain. It also quietly grades the person, so it reads better about how an idea was received than about a senior colleague''s temperament.', 'The MD was amenable to a phased rollout, though I want to be clear that nothing is signed.', '[{"text":"You sounded out a director in the corridor about moving the deadline and they did not push back. You are reporting that to your team without overstating what you have.","setting":"work"},{"text":"A vendor has hinted they could flex on the licence terms, and your sponsor asks how the conversation went.","setting":"work"},{"text":"A dataset turns out to be clean and regular enough that a simple model handles it, and you are explaining in review why nothing more elaborate is needed.","setting":"work"},{"text":"You floated Christmas at your parents'' rather than hers and your partner did not object. Her sister asks whether it is settled.","setting":"life"},{"text":"You asked the landlord about getting a cat and got a shrug rather than a no.","setting":"life"}]', '["Handling something delicate so smoothly that the difficulty never shows.","Aware of something and visibly taking it into account when you decide.","Deciding as you go, taking your lead from how things actually develop.","A senior person putting their own standing behind a piece of work and spending it there.","Progress won into territory that was previously closed to you, such as an account or a market."]', '["verifiability","substrate","modality","nontrivial","deliberate"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
