INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_unequivocal', 'unequivocal', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_unequivocal_0', 'e_unequivocal', 0, 'unequivocal', '["unequivocally"]', 'Stated so clearly that it can only be read one way.', 'It is as much a claim about your own certainty as about the thing, which is an invitation: call the results unequivocal and one awkward case takes the whole sentence down with it. It belongs to statements and evidence rather than to people, so support, instructions, and findings can be unequivocal and a sponsor cannot. Used about your own view it can also come across as shutting the discussion rather than winning it.', 'The board came back unequivocal on this: no client data leaves the tenancy, under any structure.', '[{"text":"You are relaying a decision from the top that came with no conditions attached, and people keep asking where the wiggle room is.","setting":"work"},{"text":"A regulator''s letter allows exactly one reading, and you are summarising it for a team that would very much like it to allow two.","setting":"work"},{"text":"Your doctor''s advice about the medication came without a single hedge, and a relative keeps hunting for the loophole.","setting":"life"},{"text":"A friend asks whether your partner is genuinely on board with the move. She said yes in a way that left nothing open.","setting":"life"}]', '["Made deliberately hard to understand.","Big enough to matter, said of an amount or a change.","Aware of something and taking it into account.","Covering a wide range of cases rather than a narrow one.","True on the whole, allowing for exceptions nobody is going to list."]', '["primitive","persist","fan-out","advocate for","verifiable rewards"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
