INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_esoteric', 'esoteric', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_esoteric_0', 'e_esoteric', 0, 'esoteric', '[]', 'Understood by only a small group, because it assumes background that most people lack.', 'It can flatter or dismiss and you rarely control which. Call a colleague''s specialism esoteric and you may mean it is deep, but the room usually hears that it is irrelevant to anyone who matters. It is also not a synonym for difficult or technical: plenty of hard things are widely understood, and using it that way marks you as having found something merely unfamiliar.', 'Put the evaluation methodology in an appendix. It is esoteric for this audience and we will lose them in two slides.', '[{"text":"A friend''s hobby has its own vocabulary and a worldwide forum of about two hundred people, and you are describing it to someone at a party.","setting":"life"},{"text":"You bought a book on medieval music notation and could not get past the opening chapter without the background it assumes you have.","setting":"life"},{"text":"Your uncle''s argument over dinner rests entirely on a school of economics almost nobody outside it has heard of.","setting":"life"},{"text":"You are cutting a section from a board deck because the only people who would enjoy it all sit on your own team.","setting":"work"},{"text":"A film you loved turns out to have a following of a few thousand people who trade references you had to look up.","setting":"life"}]', '["So small or so easy that it does not deserve the time it would take to discuss it.","Harder or bigger than the person asking has assumed.","Made deliberately hard to follow so that the plain version stays out of reach.","What someone can do but cannot fully explain, such as judgement, feel, or a sense of fit.","The accumulated history one organisation holds about why its own systems were built that way."]', '["in pockets","mold breaker","scaffolding","executive presence","surreptitiously"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
