INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_exacerbate', 'exacerbate', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_exacerbate_0', 'e_exacerbate', 0, 'exacerbate', '["exacerbated","exacerbating"]', 'To make a bad situation worse.', 'The word points a finger. Saying a decision exacerbated the outage assigns causation, and in a post-incident room that is heard as blame however evenly you say it, so name the mechanism unless blame is what you mean. It is also strictly about worsening something bad, so exacerbating demand or exacerbating growth is a mistake the careful listeners in the room will catch.', 'The retry logic did not cause the outage, but it exacerbated it. We hammered a service that was already on its knees.', '[{"text":"In a post-incident review you need to say that an automatic retry turned a small failure into a two-hour one, without putting it on the person who wrote it.","setting":"work"},{"text":"A hiring freeze meant to save money has made the delivery backlog worse, and you are explaining that to the sponsor who ordered the freeze.","setting":"work"},{"text":"Your neighbour''s fix for the damp has trapped more water in the wall than there was before.","setting":"life"},{"text":"A friend keeps looking at their ex''s photos and cannot understand why each week is harder than the one before.","setting":"life"}]', '["To put right what went wrong.","To avoid it on principle.","To back a claim with evidence someone else can check.","To keep at something long after most people would stop.","To make something deliberately hard to understand."]', '["bespoke","substantiate","first order effects","tacit knowledge","progressive"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_exacerbate_0_recognition', 's_exacerbate_0', 'recognition', NULL, NULL, 124, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
