INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_surreptitiously', 'surreptitiously', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_surreptitiously_0', 'e_surreptitiously', 0, 'surreptitiously', '["surreptitious"]', 'Done quietly so that nobody sees it happening.', 'It supplies a motive for the hiding, so aimed at a colleague it is an accusation wearing the clothes of an adverb. About systems it is heavier still: an agent that surreptitiously wrote to the database will be read as a security finding rather than a quirk, and the sentence outlives the meeting. About yourself it is usually light and self-deprecating, which is where most of its safe uses are.', 'Nobody signed anything off. A team had been surreptitiously pointing production traffic at the new index for a month.', '[{"text":"You checked the football score under the table during your niece''s school play.","setting":"life"},{"text":"A friend has been moving small amounts out of the joint account for months to pay for a surprise trip.","setting":"life"},{"text":"Someone at the next table is clearly photographing the menu prices and clearly does not want to be seen doing it.","setting":"life"},{"text":"You want to describe how a team kept an old system quietly running long after it was declared dead, and you are choosing how hard to make that land.","setting":"work"}]', '["In the most prominent position, where it cannot be missed.","Directly and without hedging.","Lasting only briefly, and meant to.","Done on purpose and after thought rather than by accident.","Present in scattered, isolated places rather than across the whole."]', '["amenable","inroads","wordsmith","watch outs","blanket approval"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_surreptitiously_0_recognition', 's_surreptitiously_0', 'recognition', NULL, NULL, 128, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
