INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_idempotent', 'idempotent', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_idempotent_0', 'e_idempotent', 0, 'idempotent', '["idempotency","idempotence"]', 'Safe to run more than once, because running it again leaves the same end state.', 'It is a promise other people design against. Say an endpoint is idempotent and someone will put a retry in front of it, so if a second call charges the card again or appends a second row, their outage is your sentence. Outside an engineering room it buys you nothing: with a sponsor say the job is safe to re-run, and keep the word for the people who will build on it.', 'The ingestion job has to be idempotent. The scheduler will retry it on failure and we cannot end up with last night''s rows twice.', '[{"text":"Two overlapping schedules mean a batch job can be triggered twice in the same hour, and you are writing the one property it must have before you will sign it off.","setting":"work"},{"text":"A payments integration will be retried automatically on timeout, and you are naming the requirement that keeps a customer from being charged two or three times.","setting":"work"},{"text":"In a design review someone proposes an endpoint that appends a row on every call, and you want to name what it is missing before it goes near production.","setting":"work"}]', '["Created for one use and thrown away straight after.","Able to be replaced while the system around it keeps running.","Splitting one piece of work into many parallel branches that all run at the same time.","Checkable by someone other than whoever produced it.","Describing work that runs for many steps before anyone can tell whether it worked."]', '["ephemeral","elucidate","frontier","obscure","frontrunner"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
