INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_disambiguate', 'disambiguate', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_disambiguate_0', 'e_disambiguate', 0, 'disambiguate', '["disambiguation"]', 'To make clear which of two possible meanings is the one meant.', 'It is a technical-register word, and in a business room it can sound like procedural cover for the actual fight: reach for it when two people simply want different outcomes and you look like you are managing them rather than answering them. Keep it for cases where the confusion really is about which thing a word points at, and say we disagree when that is what is happening.', 'Both teams say the client and mean different entities. Before we go further can we disambiguate that one word?', '[{"text":"Two teams use the same word for different objects, and the argument in the room is really about that rather than about the design.","setting":"work"},{"text":"A figure on a slide could be read as either a monthly or a rolling twelve-month number, and you want the author to make the wrong reading impossible.","setting":"work"},{"text":"Two people in your friendship group have the same name and you are about to tell a long story about one of them.","setting":"life"},{"text":"Someone suggests meeting next Friday and you genuinely cannot tell which Friday they mean.","setting":"life"}]', '["To make something deliberately hard to understand.","To work over the phrasing of a draft so it reads better.","To back a claim with evidence that somebody else can check.","To put right something that was wrong, such as an error or an imbalance.","To show someone a piece of work before committing to it, seeking their reaction."]', '["despondent","serialize","idempotent","executive presence","buy-in"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
