INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_community_of_practice_vs_center_of_excellence', 'community of practice vs center of excellence', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_community_of_practice_vs_center_of_excellence_0', 'e_community_of_practice_vs_center_of_excellence', 0, 'community of practice', '["CoP","communities of practice"]', 'A voluntary group of people doing the same work who meet to share what they learn.', 'Because it is voluntary you cannot hold it to a deliverable, so promising a steering group that one will own the standards promises something it has no power to enforce. Give it a budget, headcount and sign-off rights and you have built the other thing, and should say so rather than keeping the friendlier name over it. It also fails quietly: naming one costs nothing, and an empty calendar invite six months on is visible to everybody.', 'The prompt engineering group is not a governance body. It is a community of practice, and it works precisely because nobody has to come.', '[{"text":"Engineers in four product teams keep solving the same problem separately, and you want to propose a standing forum with no mandate and optional attendance.","setting":"work"},{"text":"A director asks what to call the monthly session where people demo what they tried and what failed, and you want a name that promises sharing rather than authority.","setting":"work"},{"text":"A sponsor asks how the data scientists scattered across four teams will stay aligned when you have no authority over any of them.","setting":"work"}]', '["The most senior people in an organisation, spoken of as a single group.","A people scattered from a homeland who keep a tie to it.","A funded, staffed team that owns a standard and enforces it across other teams.","The history one organisation holds about why things were built the way that they were.","What someone can do but cannot fully explain, such as judgement, feel, or a sense of fit."]', '["gravitas","front and center","trivial","frontier","sandbox"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
