INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_continuum', 'continuum', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_continuum_0', 'e_continuum', 0, 'continuum', '["continua"]', 'A smooth range with no natural breaks, where any line you draw is a choice.', 'It is a move against somebody''s categories, so it always lands as a challenge to whoever just proposed them. Used to avoid a call it is worse than useless: when the decision needs a threshold, saying the thing is a continuum without proposing where to cut reads as refusing to decide, and a sponsor will hear it that way. Do not use it where the steps are real either, because a pricing tier is not one.', 'Autonomy is not a switch, it is a continuum, and the real question is how far along it we are willing to be in the next release.', '[{"text":"A committee wants every agent sorted into autonomous or supervised, and each real system you have sits somewhere between the two.","setting":"work"},{"text":"A policy draft splits data into sensitive and not sensitive, and you have three examples that land on either side depending on who is asked.","setting":"work"},{"text":"A friend insists people are either morning people or night people, and you think the truth slides between the two rather than sitting in one box or the other.","setting":"life"},{"text":"Someone asks whether you speak Spanish. You can order dinner and you lose a phone call, so both yes and no are wrong answers.","setting":"life"}]', '["Advancing in stages, each stage going further than the last.","Unequal in a way that changes the decision, usually about a bet.","A kind of input or output a system works in, such as text, images, or audio.","Deep structural change in the conditions everyone is operating under.","One piece of work splitting into many parallel branches that all run at once."]', '["watch outs","by and large","substantiate","build that muscle","play it by ear"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_continuum_0_recognition', 's_continuum_0', 'recognition', NULL, NULL, 156, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
