INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_scaffolding_harness_sandbox', 'scaffolding/harness/sandbox', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_scaffolding_harness_sandbox_0', 'e_scaffolding_harness_sandbox', 0, 'scaffolding', '["scaffold"]', 'Temporary structure that holds work up until the real thing can stand alone.', 'The word commits you to removal. Call something scaffolding and people will remember that you said it was temporary, and will ask when it is coming out; if you have no intention of taking it out, you have handed someone a stick. It is also about supporting the real work, not being a rough version of it, so a quick first implementation is a draft, not this.', 'The manual review step is scaffolding. Once the classifier is calibrated it comes out.', '[{"text":"You hardcoded a lookup to unblock a demo and want your tech lead to know it is not meant to survive.","setting":"work"},{"text":"A sponsor asks why an automated pipeline still has a person sitting in the middle of it.","setting":"work"},{"text":"A friend is propping up a bookshelf with a stack of magazines until the brackets arrive.","setting":"life"},{"text":"You are running alongside your daughter''s bike with a hand under the saddle, and someone asks how long you plan to keep doing that.","setting":"life"}]', '["An isolated environment where code runs without touching anything real.","A rig that drives a system from outside to see how it behaves.","Lasting only briefly, and created for one use before being thrown away.","A basic building block a platform hands you and expects you to compose things out of.","The preparation done in advance of a moment where a gap would cost you dearly."]', '["substantiate","ducks in a row","long-horizon","heuristic","eschew"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
