INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_scaffolding_harness_sandbox_0_reverse', 's_scaffolding_harness_sandbox_0', 'reverse', NULL, NULL, 166, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_scaffolding_harness_sandbox_0_production', 's_scaffolding_harness_sandbox_0', 'production', NULL, NULL, 167, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_scaffolding_harness_sandbox_1', 'e_scaffolding_harness_sandbox', 1, 'harness', '[]', 'A rig built to drive a system from outside and see how it behaves.', 'In an AI room this now usually means an evaluation harness, so people may hear eval when you meant test rig. Say which you mean if the room is mixed. It also implies you built the apparatus rather than bought the numbers, so do not use it for a public benchmark you merely ran.', 'We need a harness that replays last quarter''s queries against the new model.', '[{"text":"You want something that fires realistic inputs at your agent and records what comes back, so you can compare two versions honestly.","setting":"work"},{"text":"A director asks how you will know the new model is better, and you need a word for the apparatus that answers that.","setting":"work"},{"text":"A vendor demo went well and you want to run your own inputs through their system under your own conditions before believing any of it.","setting":"work"}]', '["Temporary structure that holds work up until the real thing can stand alone.","An isolated environment where something runs without affecting anything real.","Using your own product for real work before asking anyone else to.","A specific way a system goes wrong.","The underlying layer everything else runs on."]', '["front and center","persistence","lay of the land","disparage","elucidate"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_scaffolding_harness_sandbox_1_recognition', 's_scaffolding_harness_sandbox_1', 'recognition', NULL, NULL, 168, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_scaffolding_harness_sandbox_1_identify', 's_scaffolding_harness_sandbox_1', 'identify', NULL, NULL, 169, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_scaffolding_harness_sandbox_1_reverse', 's_scaffolding_harness_sandbox_1', 'reverse', NULL, NULL, 170, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_scaffolding_harness_sandbox_1_production', 's_scaffolding_harness_sandbox_1', 'production', NULL, NULL, 171, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_scaffolding_harness_sandbox_2', 'e_scaffolding_harness_sandbox', 2, 'sandbox', '["sandboxed"]', 'An isolated place to run something where it cannot affect anything real.', 'It promises containment. If the environment can actually reach production data or spend real money, calling it a sandbox is a claim someone will hold you to, and compliance will hold you to it in writing. It also says nothing about how faithful the environment is, so do not use it when what you are promising is a realistic rehearsal.', 'Let it run in a sandbox first. I do not want it touching the live index.', '[{"text":"You are letting an agent execute code it wrote itself and want somewhere it cannot do damage.","setting":"work"},{"text":"Compliance asks what stops the new tool reading customer records during testing.","setting":"work"},{"text":"A vendor wants their engineers to try your pipeline, and you need a word for the walled-off copy you are willing to give them.","setting":"work"}]', '["Temporary structure that holds work up until the real thing can stand alone.","A rig that drives a system from outside to see how it behaves.","Present in scattered, isolated places rather than across the whole.","Using your own product for real work before you ask anyone else to.","One of the handful of cloud providers running compute and storage at planetary scale."]', '["heuristic","advocate for","diaspora","fearless forecast","finesse"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_scaffolding_harness_sandbox_2_recognition', 's_scaffolding_harness_sandbox_2', 'recognition', NULL, NULL, 172, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
