INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_persist_persistence', 'persist/persistence', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_persist_persistence_0', 'e_persist_persistence', 0, 'persist', '["persisted","persisting"]', 'To save data somewhere it will survive a restart or a refresh.', 'Engineers hear a specific promise in it, that the thing is on durable storage and will come back after a crash, so do not use it for a value you are holding in a variable or a cache. It is transitive here, and that is the tell: you persist the state. Ordinary English uses the same word intransitively for keeping at something, so the team persisted says nothing at all about data, and we persisted the results will simply not parse for anyone non-technical in the room.', 'Right now the session only lives in memory. If the pod restarts we lose the whole conversation, so we need to persist it.', '[{"text":"A prototype loses everything the user typed the moment the browser is refreshed, and you are writing the ticket for what has to change.","setting":"work"},{"text":"In a design review someone is holding session state in memory on a single node, and you want to name the missing property before it goes near production.","setting":"work"},{"text":"An architect asks where the agent''s conversation history lives after a pod restarts, and you want the verb for putting it somewhere that survives one.","setting":"work"}]', '["To turn an object in memory into bytes that can be sent over a wire.","To replace a running component without stopping the system around it.","To make a bad situation worse.","To avoid something deliberately and on principle.","To settle which of two possible readings is the one meant."]', '["hot-swap","enmeshed","run it by you","inroads","scaffolding"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_persist_persistence_0_recognition', 's_persist_persistence_0', 'recognition', NULL, NULL, 176, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_persist_persistence_0_identify', 's_persist_persistence_0', 'identify', NULL, NULL, 177, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_persist_persistence_0_reverse', 's_persist_persistence_0', 'reverse', NULL, NULL, 178, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_persist_persistence_0_production', 's_persist_persistence_0', 'production', NULL, NULL, 179, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_persist_persistence_1', 'e_persist_persistence', 1, 'persistence', '["persistent"]', 'Staying with something long after most people would have stopped.', 'Praise for persistence quietly says the person got there by not stopping, which makes it a consolation prize when the work actually succeeded on merit: told to someone whose analysis was simply the best in the room, it damns them. Persistent about a person is worse again, because in most rooms that is the word for someone who will not take no for an answer.', 'That deal closed on persistence more than anything else. She went back to them four times after we had all written it off.', '[{"text":"A friend got into medical school on their third application, and you are raising a glass to whatever it was that got them there.","setting":"life"},{"text":"Your son has been failing the same climbing route every Saturday for a month, and today he got up it.","setting":"life"},{"text":"You are writing a reference for someone whose strongest quality is that they never let a thing drop.","setting":"work"},{"text":"A neighbour finally got the council to replace the broken streetlight after a year of letters nobody answered.","setting":"life"}]', '["Weight and seriousness in how a person carries themselves.","Being aware of something and visibly taking it into account.","Tangled into something so completely that you can no longer act on your own.","Low in a way that has given up on things improving.","Alert and responsive to something, picking up its signals early and adjusting."]', '["blanket approval","asymmetric","enmeshed","surreptitiously","north star"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_persist_persistence_1_recognition', 's_persist_persistence_1', 'recognition', NULL, NULL, 180, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
