INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_primitive_0_production', 's_primitive_0', 'production', NULL, NULL, 187, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_serialize', 'serialize', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_serialize_0', 'e_serialize', 0, 'serialize', '["serialization","serialized","serialise"]', 'To turn something in memory into bytes that can be stored or sent and read back.', 'The word has a second life in performance conversations, where serializing means forcing things through one at a time, the opposite of running them in parallel. Two engineers can talk past each other for ten minutes on that, so name the format or name the bottleneck and the ambiguity goes away. With a non-technical audience it lands as noise: say we save it in a form we can send.', 'The agent state has to be serialized before it goes on the queue, and half of these objects have no clean way to do that.', '[{"text":"An object holding your agent''s working state needs to go onto a message queue, and you are explaining what has to happen to it before it can.","setting":"work"},{"text":"Two services written in different languages need to exchange the same structure, and you are choosing the format both of them will write and read.","setting":"work"},{"text":"A trained model has to be written to a file so that another process can load it back in exactly the shape it was.","setting":"work"}]', '["To replace a running component without stopping the system around it.","To split one request into many branches that run at the same time.","To avoid something deliberately and on principle.","A kind of input or output a system works in, such as text, images, audio, or video.","To make something deliberately hard to understand so the plain version stays hidden."]', '["verifiability","sleuthing","long-horizon","lend itself","dogfooding"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_serialize_0_recognition', 's_serialize_0', 'recognition', NULL, NULL, 188, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_serialize_0_identify', 's_serialize_0', 'identify', NULL, NULL, 189, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
