INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_north_star', 'north star', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_north_star_0', 'e_north_star', 0, 'north star', '["north star metric","northstar"]', 'The single outcome you steer everything else by.', 'The whole value is that there is exactly one. A deck with three north stars has none, and senior people read that as a team that has not chosen. It is also a direction rather than a commitment, so offering it as your quarterly goal hands someone a deadline for a thing you do not fully control. And it is common enough now that using it as decoration over an ordinary KPI is noticed; if the honest answer is a set of trade-offs, say that instead.', 'Time to a trustworthy answer is our north star for the year. If a feature does not move that, it waits.', '[{"text":"Three workstreams each have their own definition of success, and you want one outcome put above all of them and held there for the year.","setting":"work"},{"text":"A sponsor asks how you will choose between two features when both look good on paper, and you want to name the single measure that settles it.","setting":"work"},{"text":"You and your partner are weighing two cities, two jobs and a school, and you want to agree in advance on the one thing that matters most, so the decision is not made by whoever argues hardest at the time.","setting":"life"},{"text":"A friend is drowning in options for the year ahead and asks how you decide anything, and your honest answer is that you fix one thing and let everything else bend around it.","setting":"life"}]', '["The one currently most likely to win, said while the outcome is still open.","A number given straight, with the caveats stripped out.","The underlying layer everything above it runs on.","Real agreement from the people you need.","The most senior people, as one group."]', '["exacerbate","bolster","failure mode","despondent","panopticon"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_north_star_0_recognition', 's_north_star_0', 'recognition', NULL, NULL, 192, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_north_star_0_identify', 's_north_star_0', 'identify', NULL, NULL, 193, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
