INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_verticals_industry_verticals', 'verticals/industry verticals', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_verticals_industry_verticals_0', 'e_verticals_industry_verticals', 0, 'vertical', '["verticals","industry vertical","industry verticals"]', 'A slice of the market made up of a single industry like banking or healthcare.', 'It is a go-to-market word, not an architecture one. Saying you will take the product one of these at a time commits you in public to per-industry work: separate data, separate regulators, separate sales motion, and the immediate follow-up is which one you are starting with and what the others are waiting for. Used for a team''s internal domain it confuses anyone who hears it as a market segment.', 'The core platform stays horizontal. We only build vertical-specific pieces where the regulator forces us to.', '[{"text":"An MD asks how you plan to expand next year. The answer is one sector at a time rather than one capability at a time, and you need the word for those market slices.","setting":"work"},{"text":"A sponsor wants to know why the healthcare build costs twice what the banking one did, and you need the term for the thing that makes them effectively different products.","setting":"work"},{"text":"You are writing a strategy note that separates what every client gets from what only insurers get, and you need a heading for the second category.","setting":"work"},{"text":"In a pipeline review someone asks why the same demo lands with logistics clients and falls flat with asset managers. You want the word for the split that explains it.","setting":"work"}]', '["The underlying layer that everything above it runs on and takes for granted.","A basic building block a platform gives you and expects you to combine with others.","A funded team that holds a scarce skill in one place and sets how it is used.","One request splitting into many parallel pieces of work that run at the same time.","An isolated environment where code runs without touching anything real."]', '["substrate","tectonic shift","pick your brain","panopticon","hot-swap"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
