INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_modality', 'modality', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_modality_0', 'e_modality', 0, 'modality', '["modalities"]', 'A kind of input or output a system works in, such as text, images, audio or video.', 'In an AI room it means the kind of data and nothing else. Reaching for it where ''format'' or ''channel'' would do - a delivery modality, a training modality - is the consulting usage, and to technical listeners it sounds like a plain word in a suit. Mixed rooms are the real risk: clinicians and consultants hear ''a way of doing something'' and follow you somewhere you did not intend to go.', 'The hard part isn''t the volume, it''s that the filings arrive in three modalities and only one of them is clean text.', '[{"text":"A sponsor asks why letting the assistant accept voice is not a small change. You want the term for the kind of input, so you can say the pipeline handles exactly one of them today.","setting":"work"},{"text":"You are writing an evaluation plan and need one heading that covers text, images and audio together as a single category of thing.","setting":"work"},{"text":"A colleague argues the product should answer in speech as well as on screen. You want one word for what they are proposing to add, rather than a list.","setting":"work"},{"text":"You are explaining to your father why his phone can now answer a question about a photograph as well as a typed question, and you want the word for those different kinds of input.","setting":"life"}]', '["A rule of thumb that gets you a good enough answer quickly.","The place where raw tables and columns are mapped onto words the business uses.","Temporary structure that holds work up until the real thing can stand on its own.","One of the handful of cloud providers running compute and storage at planetary scale.","A people scattered from a homeland who keep a tie to it, and that scattering itself."]', '["hyperscaler","nontrivial","buy-in","sleuthing","exacerbate"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
