INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_flywheel_effect', 'flywheel effect', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_flywheel_effect_0', 'e_flywheel_effect', 0, 'flywheel effect', '["flywheel","flywheels"]', 'A cycle where each turn feeds the next, so growth gets easier the longer it runs.', 'It claims a specific mechanism, so you should be able to say each step of the loop out loud before you use it - in an investment room someone will ask you to draw it, and growth that is merely fast has no loop in it at all. It also carries a built-in excuse for a flat early stretch, which is a very convenient thing to reach for when your numbers are flat. Bezos put the word in every strategy deck for a decade, so in some rooms it arrives pre-discounted as consultant language.', 'Every deployment hands us the failure cases the next model trains on. That''s the flywheel, and honestly it''s the only moat we have.', '[{"text":"You are explaining to an investor why the product improves the more it is used, and you want a single term for that loop instead of three sentences of mechanism.","setting":"work"},{"text":"A sponsor asks why usage sat flat for two quarters and then bent sharply upward, and you want the term for growth that starts slowly and then compounds.","setting":"work"},{"text":"In a strategy session someone claims the product has a moat. You want the word for the loop they would have to be able to draw for that claim to survive the next question.","setting":"work"},{"text":"A bakery near you got busy because the queue outside made passers-by curious, and the queue got longer, and you want a word for what happened to it.","setting":"life"}]', '["A rig that drives a system to see how it behaves under conditions you choose.","Progress won into territory that was previously closed to you.","A people scattered from a homeland who keep a tie to it.","A structure where everyone can be watched at any moment and nobody knows when they are.","The unwritten history an organisation holds about why its own systems were built that way."]', '["squarely","by and large","enmeshed","executive presence","semantic layer"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
