INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_long_horizon_task', 'long-horizon (task)', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_long_horizon_task_0', 'e_long_horizon_task', 0, 'long-horizon', '["long horizon","long-horizon task","long horizon task","long-horizon tasks"]', 'Running for many steps before anyone can tell whether it worked.', 'It is about the number of steps and the delay before feedback, not about the calendar. Using it for a project that is merely slow - a two-year migration with a checkpoint every fortnight - borrows research vocabulary for ordinary scheduling, and the people who use the term precisely will hear that. In an investment room the second word already means holding period, so a mixed audience takes you to be talking about time frames rather than about what makes a task hard for an agent.', 'Single-shot extraction is basically solved. The long-horizon work - chase the filing, reconcile it, come back with a memo - is where it still falls over.', '[{"text":"You are explaining to a director why an agent that answers questions well still cannot be trusted with a whole reconciliation end to end, and you need the term for the second kind of work.","setting":"work"},{"text":"In an evaluation design meeting you need a name for the category of test where the system only discovers at the very end whether it got there.","setting":"work"},{"text":"A supplier demos an agent completing a task in three steps and claims it generalises. You want the term for the class of work their demo never touched.","setting":"work"},{"text":"A sponsor asks why one task of forty steps is harder for a system than forty tasks of one step, and you want the standard term for the first kind.","setting":"work"}]', '["Safe to run more than once, since the second run leaves things exactly as the first did.","Understood by only a small group, because it assumes background that most people lack.","Built for one customer rather than taken off the shelf.","Lasting only briefly, and meant to.","So small or so easy that it is not worth the time it would take to discuss."]', '["lean on","run it by you","exacerbate","diaspora","blanket approval"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
