INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_asymmetric', 'asymmetric', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_asymmetric_0', 'e_asymmetric', 0, 'asymmetric', '["asymmetry","asymmetrical","asymmetries"]', 'Unequal on the two sides, usually a small downside against a much larger upside.', 'It says nothing about likelihood, so calling something asymmetric is not calling it a good idea - a lottery ticket is asymmetric. It also only earns its place if you can say which side is bigger and roughly by how much; used bare it dresses a hunch as analysis, and an investment committee is precisely the room that asks for the two numbers. Technical listeners have the word already spoken for by encryption and by information asymmetry, so name what is uneven.', 'The pilot is asymmetric: worst case we lose a quarter of one team''s time, best case we retire two vendors.', '[{"text":"You are pitching a small pilot to a sponsor. The cost is capped at one quarter of a team''s time and the payoff, if it lands, is retiring two suppliers, and you want the word for that shape.","setting":"work"},{"text":"An investment committee asks why you would take a chance that will probably fail, and your answer is about the size of the two outcomes rather than the odds.","setting":"work"},{"text":"You are arguing against a change that saves a modest amount of money and risks a regulatory finding, and you need the word for a bet whose shape runs the wrong way.","setting":"work"},{"text":"A friend asks whether to send a speculative application for a job they almost certainly will not get. It costs them an evening and it could change their decade.","setting":"life"},{"text":"You are talking your partner out of skipping travel insurance to save forty pounds on a trip that has already cost thousands.","setting":"life"}]', '["Harder or larger than the person asking has assumed it would be.","Big enough to matter, said of an amount, a change, or a piece of work.","A range with no natural joints in it, where the cases shade into one another.","A structure where everyone can be watched at any moment and nobody knows when they are.","Training signal a machine can check for itself rather than a person having to judge it."]', '["front and center","amenable","fan-out","substantial","disparage"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
