INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_play_it_by_ear', 'play it by ear', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_play_it_by_ear_0', 'e_play_it_by_ear', 0, 'play it by ear', '["playing it by ear","played it by ear","play things by ear","play that by ear","play the rest by ear"]', 'To decide as you go, guided by what actually happens rather than by a set plan.', 'It tells the room there is no plan, and how that lands depends entirely on who is in it. With friends it sounds relaxed; to a sponsor or a steering committee it sounds unprepared, and the usual reply is a request for the very plan you have just admitted you do not have. It is only defensible when the information you need genuinely does not exist yet, so name what you are waiting on - otherwise people file it as improvisation dressed up as flexibility.', 'We''ll fix the first two milestones and play the rest by ear until the vendor confirms their dates.', '[{"text":"A friend asks what time you will get to the party and whether you are staying for dinner, and you would rather not commit to either.","setting":"life"},{"text":"You are going to a city for two days with nothing booked past the first night, and a relative asks for your itinerary.","setting":"life"},{"text":"A director asks how you intend to handle the questions in a session where you do not yet know who is attending or what mood they will be in.","setting":"work"},{"text":"The supplier has not confirmed their dates, so the second half of the plan cannot be fixed yet, and you need a way to say so that does not sound unprepared.","setting":"work"}]', '["To put right something that has gone wrong.","To avoid something on purpose, having had the option to take it.","A rule of thumb that gets you a good enough answer quickly, because it usually works.","The preparation you do in advance of a moment where any gap would cost you.","Temporary structure that holds the work up until the real thing can stand on its own."]', '["esoteric","idempotent","fan-out","lay of the land","by and large"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
