INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_pick_your_brain', 'pick your brain', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_pick_your_brain_0', 'e_pick_your_brain', 0, 'pick your brain', '["pick your brains","picking your brain","picked your brain","pick his brain","pick her brain","pick their brain","pick someone''s brain","pick a brain"]', 'To ask someone to share what they have learned, in an informal conversation.', 'It sounds casual while asking for open-ended time, and the whole cost falls on them. Sent cold to someone senior with no boundary on it - no length, no topic, no reason it has to be them - it reads as entitled, and to some it reads as asking them to do your thinking. Put twenty minutes and a specific question around it and it becomes easy to say yes to. The register is informal: right in a message to a colleague, wrong in a first approach to an MD you have never met.', 'You''ve done two of these migrations. Could I pick your brain for twenty minutes before we commit to a design?', '[{"text":"A colleague has already done two migrations like the one you are starting, and you want half an hour of informal conversation rather than a document from them.","setting":"work"},{"text":"You are messaging someone in another department whose experience you need, and you want a phrase that makes the request sound small and easy to accept.","setting":"work"},{"text":"A friend of a friend has renovated a flat like yours and you want an hour of their time and, more usefully, their mistakes.","setting":"life"},{"text":"Your cousin has just been through the visa process you are about to start, and you want to sit down with them and ask everything.","setting":"life"}]', '["To make something deliberately hard to follow.","To put right something that was wrong.","To rework the exact phrasing of a draft without changing what it says.","To dig patiently through records for something nobody hid but nobody wrote up either.","To back a claim with evidence that somebody other than you can go and check it."]', '["frontier","wordsmith","semantic layer","center of excellence","play it by ear"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
