INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_by_and_large', 'by and large', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_by_and_large_0', 'e_by_and_large', 0, 'by and large', '[]', 'On the whole, allowing for exceptions that do not change the conclusion.', 'It signals you have not checked the exceptions. Safe in conversation, risky in writing that will be scrutinised, because this is exactly where someone asks which cases you are excluding.', 'By and large the migration went clean. Two services needed manual work.', '[{"text":"Your sponsor asks how the rollout went. It went well, and there were two ugly cases you would rather not itemise right now.","setting":"work"},{"text":"You are summarising six months of model performance to a board and do not want to caveat every quarter.","setting":"work"},{"text":"Someone asks how your holiday was. Good, apart from one bad day you do not want to dwell on.","setting":"life"},{"text":"A friend asks whether you liked a novel. You did, with reservations you are not going to list over dinner.","setting":"life"},{"text":"A colleague asks whether the new review process is working. It is, for most teams, and you do not want to claim it is universal.","setting":"work"}]', '["Directly and without hedging, usually about where something belongs.","Done quietly so as not to be seen doing it.","Present in scattered places rather than across the whole of something.","Proceeding by small additions, with each one standing on its own without the rest.","So little known, or so unclear, that most people would not be able to follow it."]', '["community of practice","harness","scaffolding","amenable","sponsorship"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_by_and_large_0_recognition', 's_by_and_large_0', 'recognition', NULL, NULL, 264, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
