INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_front_and_center', 'front-and-center', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_front_and_center_0', 'e_front_and_center', 0, 'front and center', '["front-and-center","front and centre","front-and-centre"]', 'In the most prominent position, where nobody can miss it.', 'It is a claim about visibility, not about importance, and the two come apart: whatever you put there also takes the questions, so the phrase is really a decision about exposure. That is doubly true of a person - being put there is not purely a compliment, because whoever stands there answers for the thing. The register is spoken and distinctly American, so in a formal board paper it reads breezier than everything around it.', 'Put the cost of doing nothing front and center. Everything else can go in the appendix.', '[{"text":"You are advising a colleague on a board deck, and the risk they buried on slide fourteen is the one thing the board most needs to see.","setting":"work"},{"text":"A sponsor asks what actually changed in the new strategy, and the honest answer is that a topic which used to sit in the appendix is now the first thing anybody sees.","setting":"work"},{"text":"You are hanging pictures and want one particular photograph in the most visible spot in the room rather than tucked off to the side.","setting":"life"},{"text":"A friend asks what you are prioritising now that the children have left home, and the answer is something you used to squeeze in around everything else.","setting":"life"}]', '["Done quietly so as not to be seen doing it.","Lasting only briefly, and meant to.","Present in scattered, isolated places rather than across the whole.","Understood by only a small group, because it assumes background most people lack.","Big enough to matter, said of an amount or a change."]', '["modality","substantiate","long-horizon","executive presence","flywheel effect"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_front_and_center_0_recognition', 's_front_and_center_0', 'recognition', NULL, NULL, 272, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
