INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_build_that_muscle', 'build that muscle', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_build_that_muscle_0', 'e_build_that_muscle', 0, 'build that muscle', '["build the muscle","building that muscle","build this muscle","built that muscle","build that muscle up","build muscle"]', 'To build a skill through repeated practice instead of one-off training.', 'It says the ability is missing today. Said about another team that is a criticism in gym clothes; said about your own it is an admission, which is fine only if the next sentence names the actual reps. To a team already at capacity it lands as more work with no more people. It is also coaching-deck language, so in a written board paper it reads as a slogan and invites the obvious question of what the exercise is and who is doing it.', 'We can buy the first three evaluations in. If we want this capability in-house, at some point we have to build that muscle ourselves.', '[{"text":"Your team keeps handing evaluation work to a consultancy, and you want to argue for doing it in-house repeatedly until they are good at it.","setting":"work"},{"text":"A director asks why you are giving juniors the client presentations when a senior would do a better job today, and your answer is about where the team is in a year.","setting":"work"},{"text":"A friend says they are simply hopeless at cooking, and you want to say the ability is not fixed and comes from doing it over and over.","setting":"life"},{"text":"You have started running twice a week and are explaining to a sceptical relative why the first month feeling awful is the whole point.","setting":"life"}]', '["To use your own product for real work before asking anyone else to.","To make a bad situation worse than it already was.","To dig patiently through records for something that was never hidden on purpose.","To replace a running part of a system without stopping the system around it.","To put right something that was wrong."]', '["nontrivial","attuned","mold breaker","persist","pick your brain"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
