INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_tacit_institutional_knowledge_0_production', 's_tacit_institutional_knowledge_0', 'production', NULL, NULL, 283, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_tacit_institutional_knowledge_1', 'e_tacit_institutional_knowledge', 1, 'institutional knowledge', '["institutional memory"]', 'The history an organisation holds about itself and never got around to writing down.', 'It is usually deployed as an argument for keeping somebody, so be careful whose leverage you are describing: telling a sponsor that a contractor holds it is either a case for retaining them or an admission that you allowed a single point of failure to form. And unlike judgement, this can be written down, so saying it is institutional is not an explanation of why it is undocumented - it is a description of the problem, and the obvious next question is what you are doing about it.', 'When Martin goes we lose the institutional knowledge of why the reconciliation runs at four in the morning, and not one line of it is written down.', '[{"text":"A colleague who has been here since before the merger retires in March, and nobody else can say why half the exceptions in the billing system exist.","setting":"work"},{"text":"A new director asks why a job runs at four in the morning, and the reason is a decision taken in 2014 that only two people still remember.","setting":"work"},{"text":"You are making the case for a proper handover budget, and the thing at risk is history held in people''s heads rather than any skill you could hire for.","setting":"work"},{"text":"The committee at your sports club has turned over completely and no one left can say why the fixtures are arranged the way they are.","setting":"life"}]', '["A basic building block a platform hands you and expects you to compose with.","The one outcome you steer by while everything else stays negotiable.","A structure where everyone can be watched at any moment and nobody knows when.","One of the handful of cloud providers operating at a size where compute is effectively unlimited.","A voluntary group of people who do the same kind of work and meet to trade what they know."]', '["contrived","flywheel effect","cognizant","nontrivial","deliberate"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
