INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_mold_breaker', 'mold breaker', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_mold_breaker_0', 'e_mold_breaker', 0, 'mold breaker', '["mold-breaker","moldbreaker"]', 'Someone or something that does not fit the usual pattern and changes what people expect.', 'It is a compliment in a room that rewards novelty and a warning label in a room that rewards precedent. Say it about a proposal to a steering committee and half of them hear unproven. Said about yourself it is unusable.', 'She''s a mold breaker for that seat, and that''s exactly the argument for hiring her.', '[{"text":"You are backing a candidate whose CV looks nothing like anyone else''s who has held the role, and you want the mismatch to sound like the reason to hire her.","setting":"work"},{"text":"A steering committee asks why one team keeps proposing things nobody else in the firm would have thought of. You want a compact phrase for what that team is.","setting":"work"},{"text":"You are introducing a new director whose whole appeal is that she does not resemble the last three people in the job.","setting":"work"},{"text":"A friend''s daughter skipped university to start a business, and you want a phrase for how far outside the family pattern that is.","setting":"life"},{"text":"You are describing a musician whose records sound like nothing else the genre produces.","setting":"life"}]', '["A senior person who puts their own standing behind a piece of work and spends it to help.","A voluntary group of people doing the same kind of work who meet to trade what they learn.","The accumulated history an organisation holds about why its systems were built that way.","The most senior people in an organisation, spoken of as one group.","Someone who argues your case in rooms you are not in."]', '["sponsorship","sandbox","surreptitiously","wordsmith","verifiable rewards"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
