INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_lend_itself', 'lend itself', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_lend_itself_0', 'e_lend_itself', 0, 'lend itself', '["lends itself","lend themselves","lends itself to"]', 'To have qualities that make a particular use easy or natural.', 'It is a deliberately weak claim that people hear as an endorsement. It says good fit, not it will work, and that gap is your escape route later, which a sharp sponsor will notice you leaving open. The same phrase turns critical when what follows is bad, so the object sets the temperature.', 'Reconciliation lends itself to this — the rules are stable and every answer is checkable.', '[{"text":"An MD asks which of five processes you would automate first, and you want to say one of them is naturally shaped for it without promising the outcome.","setting":"work"},{"text":"You are pushing back on a proposed use case where the data is noisy and the answer is a judgement call, so the method fits it badly.","setting":"work"},{"text":"Reviewing a new metric, you want to warn that the way it is defined makes it very easy for teams to game.","setting":"work"},{"text":"A friend asks whether a novel would work as a film, and you think its structure is naturally suited to it.","setting":"life"},{"text":"You are choosing between two flats and one of them is shaped in a way that makes having people over easy.","setting":"life"}]', '["To settle which of two possible readings was meant by adding the detail that rules one out.","To rely on someone or something to carry part of the weight for you.","To ask someone to talk through what they have learned, informally and off the record.","To make a bad situation worse.","Done quietly so as not to be seen doing it."]', '["advocate","ephemeral","unequivocal","sandbox","substrate"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
