INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_bespoke', 'bespoke', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_bespoke_0', 'e_bespoke', 0, 'bespoke', '[]', 'Made for one customer or one case rather than bought off the shelf.', 'The same word flatters a client and condemns a design, so know which room you are in. In front of a buyer it means premium and tailored; in an architecture review it means unrepeatable, unsupported and expensive to keep breathing. Say it about a colleague''s system and you have criticised it.', 'Every one of those dashboards is bespoke, which is exactly why nobody can maintain them.', '[{"text":"You are explaining to a sponsor why cost per client is not coming down: nothing built so far can be reused for the next one.","setting":"work"},{"text":"A client asks whether they get something built for them specifically or the same thing everyone else gets, and you want the flattering word for the first.","setting":"work"},{"text":"In an architecture review you want to name the pattern where six teams have each built their own one-off version of the same thing.","setting":"work"},{"text":"A friend had a suit made to his measurements rather than bought off the rack, and you are describing the difference to someone.","setting":"life"},{"text":"You are pricing a kitchen and the quote is enormous because every unit is made to fit that one room.","setting":"life"}]', '["Advancing in stages, with each stage going further than the one before it.","Safe to run more than once, because the second run leaves things exactly as the first did.","Big enough to matter, said of an amount, a change, or a piece of work.","Low in a way that has given up on improving.","The current edge of what these systems can do."]', '["obfuscate","verifiability","continuum","broad","asymmetric"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
