INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_in_pockets', 'in pockets', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_in_pockets_0', 'e_in_pockets', 0, 'in pockets', '["in pockets of"]', 'Present only in scattered, separate places rather than across the whole.', 'It is honest and quietly deflating: a sponsor who hears adoption is in pockets hears not adopted. That makes it the right word when you are asking to connect the pockets and the wrong one when you are asking for more money to keep going as you are.', 'Adoption is real, but it''s in pockets — three teams live in it and nobody else has logged in since March.', '[{"text":"A sponsor asks whether the new tool has landed across the business. It has landed in four teams and nowhere else, and you want to be honest without sounding defeated.","setting":"work"},{"text":"You are writing a status note about where the new engineering practice has actually taken hold.","setting":"work"},{"text":"An MD asks whether data quality is a firm-wide problem. It is bad in a few specific places and fine everywhere else.","setting":"work"},{"text":"A friend asks whether a neighbourhood is safe. It mostly is, apart from a few isolated streets.","setting":"life"},{"text":"You are describing how mobile signal behaves on a route you drive: fine in scattered places, gone in between.","setting":"life"}]', '["Covering a wide range of cases rather than a narrow one, said of scope or coverage.","Tangled into something so completely that you can no longer act independently of it.","A range with no natural joints in it, where the cases shade into one another.","On the whole, allowing for exceptions nobody is going to list.","To make a bad situation worse than it already was."]', '["incremental","rectify","lend itself","pick your brain","ducks in a row"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
