INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_first_second_order_effects', 'first/second order effects', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_first_second_order_effects_0', 'e_first_second_order_effects', 0, 'first order effects', '["first-order effects","first order effect","first-order effect"]', 'The direct and immediate results of a change on the thing you changed.', 'Naming something as first order is a promise that you have thought about what comes after it, and the next question in a senior room is always what comes after it. It also collides with first-order approximation, which means roughly, so in a mixed room say which you mean before someone hears you say the number is a guess.', 'The first order effect is that reviews get faster. What I actually care about is what happens to review quality once they do.', '[{"text":"A sponsor asks what the automation will do, and you want a term for the immediate, intended result before anyone asks what comes next.","setting":"work"},{"text":"In a design review you want to separate the direct consequence of a change from everything it sets off downstream.","setting":"work"},{"text":"You are writing a business case and want to label the obvious, countable benefit separately from the speculative ones.","setting":"work"},{"text":"You are talking about a tax on sugary drinks and want the name for what it does straight away to prices, as distinct from what happens after.","setting":"life"}]', '["A loop in which each turn makes the next one easier and the whole thing speeds up.","The small set of things you know to be true once precedent has been stripped away.","A kind of input or output a system works in, such as text, images, audio or video.","Weight and seriousness in how a person carries themselves.","A slice of the market defined by the industry it serves."]', '["asymmetric","amenable","pick your brain","disparage","advocate"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
