INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_first_second_order_effects_1', 'e_first_second_order_effects', 1, 'second order effects', '["second-order effects","second order effect","second-order effect"]', 'The later results that follow once people and systems adapt to the first change.', 'It is the easiest phrase in the language to use as a veto. Raise it and you should be able to name one, or you have added doubt to someone else''s proposal without paying anything for it. People notice when it only ever arrives on other people''s ideas.', 'The second order effect is the one I''d watch: once reviewers trust the tool, they stop reading the diffs.', '[{"text":"A proposal will obviously save time, and your worry is what people will quietly stop doing carefully once it does.","setting":"work"},{"text":"You are asking a team to think past the immediate benefit of a new incentive to how people will behave once they work out how it is measured.","setting":"work"},{"text":"In a risk review you want the phrase for harm that only appears after everyone has adapted to the new system.","setting":"work"},{"text":"A road near you is being widened, and you want the phrase for how traffic tends to grow to fill it.","setting":"life"},{"text":"A friend describes a rule their building introduced, and you want the term for what residents promptly started doing to get around it.","setting":"life"}]', '["The place where raw tables and columns are mapped onto the words the business uses.","A funded, staffed team that concentrates a scarce skill in one place and sets how it works.","Temporary structure that holds work up until the real thing can stand without it.","To work over the exact phrasing of something already drafted.","The most senior people in a firm, spoken of as one group."]', '["deliberate","daily driver","tacit knowledge","hot-swap","disparage"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
