INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_failure_mode_s', 'failure mode/s', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_failure_mode_s_0', 'e_failure_mode_s', 0, 'failure mode', '["failure modes"]', 'A specific way a system goes wrong, rather than the fact that it might.', 'The phrase invites a list, so raising failure modes without having any makes you sound anxious rather than rigorous. Said about a person it changes character entirely: his failure mode is going quiet is affectionate between peers and clinical the moment it is said upward, or about someone who is not in the room.', 'The failure mode I care about isn''t a wrong answer, it''s a confident wrong answer that nobody checks.', '[{"text":"A sponsor asks whether the agent is safe to deploy, and you want to talk about the specific ways it goes wrong rather than quote him a percentage.","setting":"work"},{"text":"In a design review you want the team to enumerate the particular shapes of breakage instead of saying the whole thing is risky.","setting":"work"},{"text":"You are writing a post-incident memo and need a term for the one recurring pattern sitting behind three separate outages.","setting":"work"},{"text":"A friend always argues the same way when he is tired, and you want a term for that repeating pattern of going wrong.","setting":"life"},{"text":"You are explaining to a relative why the cheap appliance you both bought always dies in exactly the same way.","setting":"life"}]', '["A basic building block a platform hands you and expects you to compose with.","The accumulated history one organisation holds about why it does things its way.","An isolated environment where something can run without touching anything real.","To put right something that was wrong.","Open to something without having agreed to it yet."]', '["obfuscate","cognizant","verbose","flywheel effect","heuristic"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
