INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_verifiability_verifiable_rewards', 'verifiability/verifiable rewards', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_verifiability_verifiable_rewards_0', 'e_verifiability_verifiable_rewards', 0, 'verifiability', '["verifiable"]', 'Whether a claim can be checked by someone other than whoever made it.', 'A room hears it as a synonym for trustworthy, and it is not: a number can be perfectly verifiable and wrong. Promise it only where you can name who does the checking and against what, or you have committed to an audit trail you have not built.', 'Our advantage isn''t that the model is right more often, it''s the verifiability — every number traces back to a filing.', '[{"text":"A compliance officer asks what makes AI output acceptable inside a regulated process, and your answer is that every figure traces back to a document anyone can open.","setting":"work"},{"text":"You are arguing for the design that shows its sources over the one that is more accurate but opaque.","setting":"work"},{"text":"A board member asks why you trust one vendor''s numbers more than another''s.","setting":"work"},{"text":"A friend forwards you a health claim, and you want a word for exactly what it lacks: no way for anyone outside to check it.","setting":"life"},{"text":"You are comparing two second-hand cars and one comes with a full documented service history.","setting":"life"}]', '["The property of work that runs for many steps before anyone can tell whether it worked.","A voluntary group of people who do the same work and meet to trade what they learn.","The words a business actually uses mapped onto the raw tables underneath them.","Weight and seriousness in how a person carries themselves.","To decide as you go, taking your lead from how things develop."]', '["gravitas","harness","advocate for","run it by you","blanket approval"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
