INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_verifiability_verifiable_rewards_0_production', 's_verifiability_verifiable_rewards_0', 'production', NULL, NULL, 335, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_verifiability_verifiable_rewards_1', 'e_verifiability_verifiable_rewards', 1, 'verifiable rewards', '["verifiable reward"]', 'Training signal a machine can check on its own, like a test passing or a proof compiling.', 'The term quietly limits its own scope. Only tasks with a checkable answer qualify, and almost none of the work you are paid for — a memo, a client recommendation, a judgement call — has an answer key. Promising this on judgement-heavy work is the overclaim to avoid. In a non-technical room it also sounds like a bonus scheme, so unpack it or use plain words.', 'Coding and maths get verifiable rewards for free. Nothing in our analyst workflow has an answer key like that.', '[{"text":"You are explaining why the newest models are so strong at code and so weak at the judgement work clients actually pay for, and the difference is whether a machine can mark the answer.","setting":"work"},{"text":"An MD asks what it would take to train a model on your internal process, and your first question is whether anything in it has a checkable right answer.","setting":"work"},{"text":"In a design session you want the term for the class of training signal that needs no human rater because correctness is mechanical.","setting":"work"},{"text":"You are pushing back on a plan to fine-tune on senior analysts'' opinions, where nothing can be marked automatically.","setting":"work"}]', '["The accumulated history an organisation holds about why its systems were built the way they were.","A voluntary group of people who do the same kind of work and meet to trade what they are learning.","The one outcome you steer by, held fixed while everything else stays negotiable.","A slice of the market defined by the industry it serves.","To work over the exact phrasing of something already written."]', '["top brass","trivial","heuristic","build that muscle","deliberate"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
