INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_substrate', 'substrate', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_substrate_0', 'e_substrate', 0, 'substrate', '[]', 'The base layer that everything built above it runs on and takes for granted.', 'The word is borrowed from geology and biology and it arrives sounding grand, which is the trap. Calling your service a substrate claims other things genuinely depend on it, and someone in the room can check that; if two teams call your API, the honest word is shared service. It also flattens what it names, so describing another team''s product that way can land as demoting them to plumbing.', 'Identity and audit are substrate. Nobody should be building either of them per product.', '[{"text":"You are arguing that authentication and logging get built once for everyone instead of separately by each product team.","setting":"work"},{"text":"A director asks what the platform team actually delivers, and you want a word for the layer everything else simply assumes is there.","setting":"work"},{"text":"In an architecture review you want to name the foundation that would have to be replaced first if you ever changed cloud providers.","setting":"work"},{"text":"Talking with a friend about how much of ordinary daily life quietly rests on the electricity grid.","setting":"life"},{"text":"You are describing a shared language as the thing an entire culture''s humour is built on top of.","setting":"life"}]', '["A voluntary group of people doing the same work who meet to trade what they learn.","Temporary structure that holds work up until the real thing can stand on its own.","A number or a call given straight, with all the caveats stripped out of it.","To avoid something deliberately and on principle.","Low in a way that has given up on things improving."]', '["esoteric","superset","mold breaker","harness","broad"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
