INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_dogfooding', 'dogfooding', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_dogfooding_0', 'e_dogfooding', 0, 'dogfooding', '["dogfood","eat your own dog food","eating our own dog food"]', 'Using your own product for real work before asking anyone else to use it.', 'The bar is higher than people claim. Installing your own tool is not dogfooding unless something you care about breaks when it breaks. It is also an internal word with a self-congratulatory edge, and said to a client it raises the question it was meant to settle: if you had to tell me you use it, who else does?', 'We''re not putting the assistant on anyone''s desk until we''ve been dogfooding it for a month ourselves.', '[{"text":"You are arguing the team should run its own weekly reporting on the platform it wants to sell internally, before anyone outside is asked to touch it.","setting":"work"},{"text":"A sponsor asks how you will find the rough edges before a client does.","setting":"work"},{"text":"Someone proposes a launch date and you want the phrase for the month of real internal use you want in front of it.","setting":"work"},{"text":"You are explaining why one team''s tool has an unusually good workflow: they live inside it every single day.","setting":"work"}]', '["A loop in which each turn makes the next one easier, so the whole thing speeds up.","The accumulated history one organisation holds about why it works the way it does.","A slice of the market defined by the industry it serves.","Weight and seriousness in how a person carries themselves.","To make a bad situation worse."]', '["modality","first principles","asymmetric","hyperscaler","vertical"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_dogfooding_0_recognition', 's_dogfooding_0', 'recognition', NULL, NULL, 344, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
