INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_squarely', 'squarely', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_squarely_0', 'e_squarely', 0, 'squarely', '[]', 'Directly and without hedging, usually about where something belongs or who owns it.', 'It works about accountability and category fit, and sounds odd about physical or genuinely uncertain things. If the thing really is contested, squarely overclaims and invites someone to push back on exactly that.', 'Cost governance sits squarely with the platform team, not with each product.', '[{"text":"A director asks who owns model evaluation. It is the platform team, and you want to say so in a way that ends the question.","setting":"work"},{"text":"Legal asks whether the new regulation covers your product. It does, entirely, and you want one adverb that removes the wiggle room.","setting":"work"},{"text":"You are writing a post-incident memo and need to place accountability without softening it.","setting":"work"},{"text":"You forgot a friend''s birthday. You want to take the blame without excuses or explanation.","setting":"life"},{"text":"Someone asks whether a film counts as science fiction. It does, unambiguously, and you want to say so without qualifying.","setting":"life"}]', '["Tangled into something so completely that you can no longer act or be understood alone.","A voluntary group of people doing the same kind of work who meet to trade what they learn.","Temporary structure that holds work up until the real thing can stand alone.","To make a bad situation worse.","Using far more words than the point needs."]', '["community of practice","trivial","continuum","attuned","idempotent"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_squarely_0_recognition', 's_squarely_0', 'recognition', NULL, NULL, 348, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
