INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_fan_out', 'fan-out', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_fan_out_0', 'e_fan_out', 0, 'fan-out', '["fanout","fan out","fans out"]', 'The splitting of one request into many parallel calls that must all come back.', 'In messaging and feed systems the same word means one write being delivered to many readers, so in a mixed room say which you mean before the conversation quietly forks. And whichever you mean, people hear the multiplier rather than the parallelism: say it to whoever pays the bill and the next question is cost, so arrive with the number.', 'One question fans out to eight tool calls, so a thousand users an hour is not a thousand requests an hour.', '[{"text":"An architect asks why a single user question costs so much to serve, and the answer is the number of parallel calls each one triggers.","setting":"work"},{"text":"You are describing a design where a request is split across many workers that must all return before an answer exists.","setting":"work"},{"text":"A sponsor asks why the inference bill grew much faster than the user count did.","setting":"work"},{"text":"In a review you want the term for the multiplier between one incoming request and the downstream calls it sets off.","setting":"work"}]', '["The property of a step that leaves things the same however many times it is run.","Temporary structure that holds the work up until the real thing can stand on its own.","To write something down where it will outlive whatever process made it.","The most senior people in a firm, spoken of as one group.","Understood by only a small group of insiders."]', '["ducks in a row","in pockets","superset","modality","incremental"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
INSERT INTO cards (id, sense_id, type, fsrs_state, due_at, intake_order, created_at) VALUES ('c_fan_out_0_recognition', 's_fan_out_0', 'recognition', NULL, NULL, 352, '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET intake_order = excluded.intake_order;
