INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_diaspora', 'diaspora', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_diaspora_0', 'e_diaspora', 0, 'diaspora', '["diasporic"]', 'A people scattered far from a homeland they still keep ties to.', 'The weight is the whole risk. Stretched to any dispersed group — ex-colleagues of a firm, alumni of a team, people who left a project — it sounds glib to anyone whose family actually belongs to one, and that person is more often in the room than not. If you mean a network of former employees, say alumni network.', 'The growth story there is remittances — money moving back through the diaspora — not domestic demand.', '[{"text":"A friend describes a wedding where everyone''s parents left the same country decades ago and almost nobody has been back.","setting":"life"},{"text":"You are explaining why one neighbourhood has three bakeries selling the same bread from one small region.","setting":"life"},{"text":"You are reading about a language kept alive abroad long after it faded where it began.","setting":"life"},{"text":"You are explaining to a colleague that a country''s economy runs largely on money sent home by people living overseas.","setting":"work"}]', '["The property of work that runs for many steps before anyone can tell if it worked.","A funded, staffed team that concentrates a scarce capability in one place.","A rule of thumb that gets a good enough answer quickly.","Using far more words than the point needs.","To make a bad situation worse."]', '["cognizant","first principles","second order effects","eschew","esoteric"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
