INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_sleuthing_out', 'sleuthing (out)', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_sleuthing_out_0', 'e_sleuthing_out', 0, 'sleuthing', '["sleuth","sleuth out","sleuthing out","sleuthed out"]', 'Patient digging to piece together an answer nobody has written down.', 'The word is light and slightly playful, which cuts both ways. It is generous about a colleague''s persistence, and it lets people off when the real reason you had to dig is that someone would not tell you. Said about your own week to a sponsor, it can turn two days of genuine analysis into a hobby.', 'Nobody could tell me which system owned that field, so I spent Tuesday sleuthing it out of the commit history.', '[{"text":"You spent a day working out which team owns an undocumented field by reading commit history and four-year-old tickets.","setting":"work"},{"text":"You want to credit a colleague who found the cause of a recurring cost spike that nobody had been able to explain.","setting":"work"},{"text":"A director asks how you established that two suppliers on the list are actually the same company.","setting":"work"},{"text":"You finally worked out which neighbour has been leaving flowers in the stairwell.","setting":"life"},{"text":"From photographs and a few names, you pieced together where your grandmother lived before the family moved.","setting":"life"}]', '["A funded, staffed team that concentrates a scarce capability in one place.","Permission given once and in advance to cover a whole class of decisions.","To avoid something deliberately and on principle.","The most senior people in a firm, spoken of as one.","Weight and seriousness in how a person carries themselves."]', '["incremental","fan-out","progressive","hyperscaler","contrived"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
