INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_ephemeral', 'ephemeral', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_ephemeral_0', 'e_ephemeral', 0, 'ephemeral', '["ephemerality"]', 'Lasting only a short time, and built that way on purpose.', 'In a technical room it is a claim rather than a description: say a workspace is ephemeral and the next questions are about the logs, the cache and whatever it wrote on its way out. Everywhere else it is a slightly literary word, elegant in writing and a little precious said out loud about a colleague''s short tenure or a passing mood.', 'Every agent run gets an ephemeral workspace — it exists for the task and nothing survives it.', '[{"text":"You are describing a design where each run gets a fresh environment that is destroyed the moment it finishes.","setting":"work"},{"text":"A security reviewer asks how long the credentials the agent uses stay valid, and the answer is nine minutes.","setting":"work"},{"text":"You are justifying why you do not want a permanent copy of the intermediate data kept anywhere.","setting":"work"},{"text":"You are telling a friend that the best thing about that festival is how the whole town it builds is gone by Monday.","setting":"life"},{"text":"You want a word for how quickly a mood of collective optimism came and went.","setting":"life"}]', '["Safe to run more than once, because a second run changes nothing the first did not.","A basic building block a platform hands you and expects you to compose with.","Covering a wide range rather than a narrow one.","To put right something that was wrong.","The most senior people, taken as one group."]', '["rectify","first order effects","center of excellence","failure mode","serialize"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
