INSERT INTO entries (id, headword, capture_note, tags, status, created_at, updated_at) VALUES ('e_superset', 'superset', NULL, '[]', 'ready', '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET headword=excluded.headword, tags=excluded.tags, status='ready', updated_at=excluded.updated_at;
INSERT INTO senses (id, entry_id, position, term, accepted, definition, caution, example, cues, distractors, word_distractors, prompt_version, created_at, updated_at) VALUES ('s_superset_0', 'e_superset', 0, 'superset', '["strict superset"]', 'A set that holds everything another set holds, and more besides.', 'It is a precise claim and people check it. Ninety percent of the old thing plus some new things is not a superset, and the missing ten percent is exactly what the objection will be about — so either defend nothing is lost or say covers most of. Used loosely about a person''s skills or a team''s remit it stops being maths and starts sounding like a ranking.', 'The new API is a strict superset of the old one, so nothing anybody has built stops working.', '[{"text":"You are reassuring a team that the replacement platform does everything the old one did and more, so nothing they rely on disappears.","setting":"work"},{"text":"A sponsor asks whether consolidating three tools into one will cost anybody a capability they currently have.","setting":"work"},{"text":"In an architecture review you want the exact word for a new interface that contains every method of the previous one.","setting":"work"},{"text":"You are pushing back on a migration plan because the target covers only most of what the current system does, not all of it.","setting":"work"}]', '["A slice of the market defined by the industry it serves, such as banking or health.","An isolated environment where something runs without touching anything real.","A rule of thumb that gets you a good enough answer quickly.","To make a bad situation worse.","Alert and responsive to signals, adjusting early."]', '["substantial","dogfooding","in pockets","buy-in","advocate"]', 3, '2026-08-23T13:00:00.000Z', '2026-08-23T13:00:00.000Z') ON CONFLICT(id) DO UPDATE SET term=excluded.term, accepted=excluded.accepted, definition=excluded.definition, caution=excluded.caution, example=excluded.example, cues=excluded.cues, distractors=excluded.distractors, word_distractors=excluded.word_distractors, prompt_version=excluded.prompt_version, updated_at=excluded.updated_at;
